INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63811438', 63811438, 'analyze_legacy', 'Kementerian Sekretariat Negara', 'central', 'SEKRETARIAT KEMENTERIAN SEKRETARIAT NEGARA', 'Pengadaan Jasa Perawatan Aplikasi Kementerian Sekretariat Negara', 'Jasa Lainnya', 'Tender', 'DKI Jakarta, Jakarta Pusat (Kota)', 789635000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '11 bulan', 'Permintaan pembangunan dan pengembangan yang berdasarkan arahan pimpinan tersebut mempunyai ruang lingkup pekerjaan yang sifatnya minor sampai dengan menengah serta bersifat segera harus dilaksanakan pada tahun berjalan. Untuk mensiasati kebutuhan pembangunan dan pengembangan aplikasi tersebut yang bersifat segera harus dilaksanakan, maka pembangunan dan pengembangan apliaksi tersebut dilakukan secara swakelola yang membutuhkan tenaga programmer yang tidak sedikit. Banyaknya pembangunan dan pengembangan berbagai jenis aplikasi juga menimbulkan kebutuhan akan pemeliharaan aplikasi-aplikasi tersebut untuk menjaga performa agar tetap baik selain dapat terus dikembangkan sesuai dengan kebutuhan pengguna. Untuk memenuhi kebutuhan tersebut di atas, serta mengingat keterbatasan jumlah pegawai yang memiliki kompetensi dalam bidang pembangunan dan pengembangan aplikasi di lingkungan Pusat Pengembangan dan Layanan Sistem Informasi, maka diperlukan tenaga ahli profesional yang memiliki kompetensi dalam bidang pengembangan yang bersifat minor sampai dengan menengah yang dilakukan secara kolaborasi/swakelola dalam hal pembangunan, pengembangan, dan membantu dalam memelihara aplikasi sistem informasi di lingkungan Kementerian Sekretariat Negara serta dapat memberikan masukan dan saran terkait pengembangan maupun pembangunan sistem aplikasi di Kementerian Sekretariat Negara.', 'g. Kualifikasi tenaga ahli/teknis: 1) Programmer (5 org x 12 bln ) minimal tingkat pendidikan S-1 Manajemen Informatika/ Sistem Komputer/ Teknik Informatika/ Teknik Komputer / Ilmu Komputer/ Sistem Informasi/ Matematika/Teknik Elektro  Kualifikasi ketrampilan fullstack programmer, atau backend programmer, atau frontend Programmer;  Pengalaman kerja minimal 1 (satu) tahun dalam posisi sebagai berikut: a) Software Analyst b) Software Designer c) Software Programmer d) Software Tester e) Database Administrator f) Technical Report  Menguasai bahasa pemrograman PHP, Database MySQL / PostgreSQL, Nginx, Docker, dan Linux;  Mengerti menggunakan Git;  Menguasai UI/UX design untuk kualifikasi frontend programmer; 2) Programmer Mobile Aplikasi (1 org x 1 bln ) minimal tingkat pendidikan S-1 Manajemen Informatika/ Sistem Komputer/ Teknik Informatika/ Teknik Komputer / Ilmu Komputer/ Sistem Informasi/ Matematika/Teknik Elektro Menguasai bahasa pemrograman aplikasi mobile yang sifatnya native.  Pengalaman kerja minimal 1 (satu) tahun dalam posisi jabatan diantaranya sebagai berikut: a) Software Analyst b) Software Designer c) Software Programmer d) Software Tester e) Database Administrator f) Technical Report  Menguasai bahasa pemrograman untuk aplikasi mobile yang sifatnya native;  Mampu melakukan mobile programming untuk Android (Java/Kotlin) dan iOS (Swift) [Native Application].  Mampu Melaksanakan Lifecycle Aplikasi ( Konsep, Desain, Test, Rilis, dan Support);  Mempunyai pengalaman mengembangkan aplikasi yang telah di submit pada environment iOS atau Android;  Mengerti konsep desain arsitektur aplikasi (MVP, MVC, MVVM);  Mengerti menggunakan GitHub;  Mengerti implementasi Push Notifications;  Mengerti melakukan integrasi dengan third-party application dan APIs.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1161101);
