INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63790794', 63790794, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA PUSAT', 'Penyediaan jasa pemeliharaan KDO/KDO Khusus', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 157567620, 'April 2026', 'APBD', 1, 1, '1 Paket', 'a. Pemeliharaan Metode Pemeliharaan KDO/KDO Khusus oleh pihak Penyedia pada kegiatan ini yaitu dengan melakukan pemeliharaan di bengkel penyedia jasa. b. Pengiriman. Penyedia jasa bertanggung jawab dan menjamin bahwa pemeliharaan KDO sudah sesuai spek dan kesepakatan atau persetujuan teknis. Apabila dalam pelaksanaan pekerjaan terjadi hal-hal yang menyebabkan kerusakan barang-barang inventaris Suku Dinas, maka penyedia barang wajib mengganti atau memperbaiki dengan biaya sendiri. c. Pemeriksaan Barang. Hasil pemeriksaan pekerjaan dituangkan dalam Berita Acara Pemeriksaan Barang dan ditandatangani oleh Pejabat Pembuat Komitmen dan di cek kelengkapannya oleh Pengurus Barang. d. Serah Terima Barang Setelah barang diperiksa, selanjutnya dilakukan Serah Terima Pekerjaan Barang yang dituangkan dalam Berita Acara Serah Terima Pekerjaan Barang dan ditandatangani bersama oleh penyedia barang dan pejabat pembuat komitemen dan diketahui oleh Kepala Suku Dinas selaku Pengguna Barang yang tembusannya disampaikan kepada instansi terkait lainnya. e. Penagihan Penagihan diajukan dengan mengacu kepada peraturan yang terkait dengan administrasi keuangan yang berlaku di lingkungan Pemerintahan Provinsi DKI Jakarta.', 'Persyaratan dan pengaturan 1. Spesifikasi teknis untuk bahan/material dan peralatan yang diperlukan, harus memenuhi standar yang ditetapkan. 2. Hasil yang dapat diproduksi/diselesaikan harus memenuhi standar/kualitas sesuai yang ditetapkan. 3. Pemeliharaan KDO menggunakan spare part yang diprioritaskan menggunakan produk dalam negeri. Penggunaan produk dalam negeri dilakukan sesuai besaran komponen dalam negeri pada setiap Barang/Jasa yang ditunjukan dengan nilai Tingkat Komponen Dalam Negeri (TKDN).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1163110);
