INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63770079', 63770079, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Pembuatan Monitoring dan Analisis Media Elektronik', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 100000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Paket Pembuatan Monitoring dan Analisis Media Elektronik merupakan pekerjaan sepanjang Tahun Anggaran 2026 untuk menyediakan layanan pemantauan terstruktur, pencatatan, dan analisis pemberitaan serta percakapan publik pada media elektronik (televisi, radio, dan kanal media elektronik berbasis digital) yang relevan dengan kebijakan, program, kegiatan, dan isu strategis Kementerian Ketenagakerjaan. Ruang lingkup meliputi pengumpulan data siaran/segmen pemberitaan, verifikasi dan pengelompokan isu, penilaian eksposur dan sentimen, pemetaan narasi serta aktor, penyusunan ringkasan eksekutif dan rekomendasi tindak lanjut komunikasi, serta penyajian laporan berkala (harian/mingguan/bulanan) dan laporan tematik/insidentil untuk kebutuhan pimpinan dan pengambilan keputusan, termasuk dukungan early warning atas isu yang berpotensi berdampak pada reputasi lembaga.', 'Penyediaan layanan pemantauan terstruktur terhadap pemberitaan dan percakapan publik pada media elektronik (televisi, radio, dan kanal media elektronik berbasis digital/streaming) yang relevan dengan kebijakan, program, kegiatan, dan isu strategis Kementerian Ketenagakerjaan, termasuk pengumpulan dan perekaman/kliping audio-visual beserta metadata (tanggal, jam tayang, program, narasumber), verifikasi temuan, klasifikasi dan penandaan isu (tagging) berdasarkan taksonomi yang disepakati, analisis eksposur serta kecenderungan nada pemberitaan (positif/negatif/netral), pemetaan narasi, aktor, dan potensi risiko reputasi, penyusunan rekomendasi tindak lanjut komunikasi (opsi respons, pesan kunci/talking points, dan langkah mitigasi), serta penyampaian keluaran berupa laporan berkala (harian/mingguan/bulanan) dan laporan tematik/insidentil/early warning untuk isu cepat/krisis sesuai kebutuhan pimpinan, dengan dukungan pengelolaan bank data/arsip kliping sepanjang periode 1 Januari–31 Desember 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1163220);
