INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63772236', 63772236, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Pembuatan Monitoring Akun Media Sosial', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 81120000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Pekerjaan Pembuatan Monitoring Akun Media Sosial di Lingkungan Kementerian Ketenagakerjaan dilaksanakan sepanjang tahun 2026 untuk memastikan kinerja dan pertumbuhan kanal digital Kemnaker terpantau secara sistematis dan terukur. Ruang lingkupnya meliputi pemantauan berkala terhadap penambahan pengikut (follower growth) dan tingkat keterlibatan (engagement) pada akun media sosial di lingkungan Kemnaker, mencakup akun unit teknis serta Unit Pelaksana Teknis (UPT) Pusat, melalui pengumpulan data dari masing-masing platform, konsolidasi capaian per akun, analisis tren dan perbandingan periode, serta penyusunan rekap dan laporan rutin sebagai bahan evaluasi dan pengambilan keputusan komunikasi publik di Kemnaker.', 'Kegiatan pengumpulan, verifikasi, dan konsolidasi data kinerja akun media sosial di seluruh unit kerja Kemnaker, termasuk unit teknis dan Unit Pelaksana Teknis (UPT) Pusat, pada platform yang digunakan masing-masing akun, dengan indikator minimal mencakup pertumbuhan pengikut (penambahan bersih dan tren periode) serta engagement (interaksi seperti like, komentar, bagikan/repost, simpan, klik, serta metrik jangkauan/penayangan sesuai ketersediaan analytics platform). Pekerjaan dilaksanakan melalui pemantauan berkala (harian/mingguan untuk rekap cepat dan deteksi anomali, serta bulanan untuk evaluasi kinerja), penyusunan dashboard/rekap tabel per akun dan per platform, analisis perbandingan antarperiode termasuk identifikasi konten berkinerja terbaik dan faktor pendorong/penurun kinerja, serta penyusunan laporan rutin (minimal bulanan dan rekap akhir tahun) yang memuat ringkasan capaian, tren, temuan utama, dan rekomendasi operasional untuk peningkatan kinerja komunikasi publik, dengan mekanisme koordinasi PIC dan kriteria penerimaan hasil berupa kelengkapan cakupan akun, ketepatan waktu, konsistensi data, serta tersedianya bukti data (export/screenshot/tautan analytics) untuk kebutuhan evaluasi dan akuntabilitas.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1166593);
