INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63814563', 63814563, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Direktorat Jenderal Tata Ruang', 'Fasilitasi Koordinasi Implementasi Kebijakan Satu Rencana Tata Ruang Nasional', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 232489000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1', 'Kebijakan satu rencana tata ruang/one spatial planning policy (OSPP) adalah sebuah kebijakan yang merupakan penerjemahan dari amanat Undang-Undang Nomor 26 Tahun 2007 tentang Penataan Ruang, di mana rencana tata ruang adalah sebuah instrumen kebijakan spasial untuk optimalisasi pemanfaatan ruang, baik di ruang darat, ruang laut, ruang udara, maupun ruang di dalam bumi. Kebijakan satu rencana tata ruang merupakan tindak lanjut dari kebijakan satu data dan kebijakan satu peta yang melibatkan seluruh unsur pemerintah pusat. Tujuan dari kebijakan satu rencana tata ruang adalah menjadikan rencana tata ruang sebagai referensi kebijakan terpadu dan terintegrasi. Terpadu antarpengguna ruang dengan arahan lokasi dan neraca ruang. Terintegrasi antarmatra ruang, baik matra darat, matra laut, matra udara, serta matra dalam bumi. Di tingkat nasional, OSPP diimplementasikan pada Rencana Tata Ruang Nasional yang menjadi acuan pemanfaatan ruang nasional. Rencana Tata Ruang Nasional akan menjadi acuan bagi rencana tata ruang wilayah provinsi/kabupaten/kota dan rencana rinci tata ruang nasional serta rencana induk sektoral. Untuk merumuskan sebuah referensi kebijakan terpadu dan terintegrasi yang merupakan implementasi OSPP, dalam penyusunan muatan Rencana Tata Ruang Nasional perlu melakukan diskusi lintas Kementerian/Lembaga dan lintas matra ruang. Dalam kerangka kebijakan satu rencana tata ruang, berbagai konflik tata ruang di tingkat nasional dikoordinasikan dalam sebuah rapat koordinasi lintas sektor, lintas wilayah, dan lintas pemangku kepentingan dengan menggunakan dokumen rencana tata ruang nasional sebagai acuan pengambilan kebijakan. Oleh sebab itu, pada tahun anggaran 2026 Direktorat Perencanaan Tata Ruang-Direktorat Jenderal Tata Ruang, Kementerian Agraria dan Tata Ruang/BPN melaksanakan kegiatan yang memfasilitasi penyelesaian konflik tata ruang tingkat nasional.', 'Keluaran kegiatan ini mencakup: Dokumen Implementasi OSPP/Kebijakan Satu Rencana Tata Ruang dan Evaluasi Pelaksanaan Kegiatan. Laporan penyelenggaraan kegiatan Laporan ini memuat rangkuman dan hasil-hasil kegiatan selama Tahun Anggaran 2026 disertai dengan evaluasi pelaksanaannya', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1168673);
